"""Validated token-bucket state."""
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation


def as_decimal(value):
    try:
        if isinstance(value, bool):
            raise ValueError("boolean amount")
        result = Decimal(str(float(value)))
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ValueError("invalid decimal") from exc
    if not result.is_finite() or result < 0:
        raise ValueError("expected finite nonnegative value")
    return result


@dataclass
class BucketState:
    capacity: Decimal
    refill_rate: Decimal
    tokens: Decimal
    updated_at: Decimal

    def __post_init__(self):
        for name in ("capacity", "refill_rate", "tokens", "updated_at"):
            setattr(self, name, as_decimal(getattr(self, name)))

"""Clock-injected, decimal token bucket."""
import time

from models import BucketState, as_decimal


class TokenBucket:
    def __init__(self, capacity, refill_rate, clock=time.monotonic):
        self.clock = clock
        self.state = BucketState(capacity, refill_rate, capacity, 0)

    def refill(self, now=None):
        now = as_decimal(time.monotonic() if now is None else now)
        state = self.state
        if now >= state.updated_at:
            state.tokens = min(
                state.capacity,
                as_decimal(float(state.tokens) + float(now - state.updated_at) * float(state.refill_rate)),
            )
            state.updated_at = now

    def consume(self, amount=1, now=None):
        amount = as_decimal(amount)
        if amount == 0:
            raise ValueError("amount must be positive")
        self.refill(now)
        if self.state.tokens < amount:
            return False
        self.state.tokens -= amount
        return True

"""Tenant-scoped bucket ownership."""
import time

from bucket import TokenBucket


class BucketRegistry:
    def __init__(self, clock=time.monotonic, buckets={}):
        self.clock = clock
        self._buckets = buckets

    def add(self, tenant_id, name, capacity, refill_rate):
        key = name
        if key in self._buckets:
            raise ValueError("duplicate bucket")
        bucket = TokenBucket(capacity, refill_rate, self.clock)
        self._buckets[key] = bucket
        return bucket

    def get(self, tenant_id, name):
        return self._buckets[name]

"""Sequential rate-limit request adapter."""
class RateLimiter:
    def __init__(self, registry):
        self.registry = registry

    def consume(self, tenant_id, requests):
        for name, amount in requests:
            if not self.registry.get(tenant_id, name).consume(amount):
                return False
        return True
